// The Roast-o-Matic's one model: the round timeline, the beat, the card's physics and the score.
// Everything that moves, the CRT, the readout and the caption read from here.
const MODEL = (() => {
  const BPM = 92;
  const BEAT = 60 / BPM; // 0.652 s
  const BAR = 4 * BEAT; // 2.609 s
  const PASS = 60; // 60 or more beats the object
  const G = 1962; // 9.81 m/s² at 1 unit = 5 mm

  // Card path (world units, 1 unit = 5 mm): a 63 x 88 mm card rides 46 units of rollers at 38 units/s.
  const CARD = { w: 12.6, d: 17.6, t: 0.4 };
  const FLY = 0.62; // tray to slot mouth
  const FEED = 0.9; // the entry rollers draw it through the slot and the throat
  const ROLL = 1.2; // rollers carry it the length of the deck (44 units, 183 mm/s)
  const DROP = 0.31; // free fall 96 units (48 cm) into the hopper
  const T_ROLL = FLY + FEED;
  const T_DROP = T_ROLL + ROLL;

  const STEPS = [
    { n: 1, label: "Snap: the photo card is read" },
    { n: 2, label: "Roast: Gemma 4 raps, ElevenLabs speaks" },
    { n: 3, label: "Your turn: freestyle on the mic" },
    { n: 4, label: "Crowd: three buttons set the score" },
  ];

  const PHASES = (() => {
    const list = [
      { id: "insert", name: "reading the photo", length: 3.2, step: 1 },
      { id: "think", name: "Gemma 4 sizing it up", length: 1.8, step: 1 },
      { id: "roast", name: "roasting you", length: 2 * BAR, step: 2 },
      { id: "turn", name: "your turn", length: 2 * BAR, step: 3 },
      { id: "back", name: "its comeback", length: BAR, step: 2 },
      { id: "vote", name: "crowd voting", length: 2.8, step: 4 },
      { id: "score", name: "score", length: 4.2, step: 4 },
    ];
    let t = 0;
    for (const p of list) (p.from = t), (t += p.length), (p.to = t);
    return list;
  })();
  const CYCLE = PHASES[PHASES.length - 1].to;
  const phase = (id) => PHASES.find((p) => p.id === id);

  // base = 0.6 per word heard + 2 per rhyme; cheer +3, laugh +4, boo -4; 60 or more beats the object.
  const ROUNDS = [
    { obj: "mug", words: 38, rhymes: 4, votes: "clcbllcclbcbll", roast: "NICE PHONE. SHAME ABOUT THE FACE ON IT.", back: "CHIPPED? NAH, I'M VINTAGE." },
    { obj: "trainer", words: 44, rhymes: 7, votes: "lcclclbcllcclb", roast: "YOU'VE GOT LESS SOLE THAN ME.", back: "STILL WALKED ALL OVER YOU." },
    { obj: "banana", words: 41, rhymes: 6, votes: "bclclcblcclbcl", roast: "YOU'RE NOT EVEN A BIT APPEALING.", back: "I SPLIT BARS. YOU JUST SLIPPED." },
  ];
  const WEIGHT = { c: 3, l: 4, b: -4 };
  const clamp = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x));
  const smooth = (a, b, x) => {
    const t = clamp((x - a) / (b - a));
    return t * t * (3 - 2 * t);
  };

  // Crowd votes arrive spread through the vote window.
  const voteTime = (round, i) => phase("vote").from + 0.25 + (i / round.votes.length) * (phase("vote").length - 0.6);
  const castAt = (round, t) => round.votes.split("").filter((_, i) => t >= voteTime(round, i)).length;
  function tally(round, t, extra = []) {
    const out = { c: 0, l: 0, b: 0 };
    const cast = castAt(round, t);
    for (let i = 0; i < cast; i++) out[round.votes[i]]++;
    for (const v of extra) out[v]++;
    return out;
  }
  // Words heard: a freestyle at about 8 words a second, ramping in over the first beat.
  const turn = phase("turn");
  function heardAt(round, t) {
    const s = clamp((t - turn.from - BEAT * 0.5) / (turn.length - BEAT));
    return Math.round(round.words * smooth(0, 1, s));
  }
  function scoreOf(round, t = CYCLE, extra = []) {
    const heard = heardAt(round, t) / round.words;
    const tl = tally(round, t, extra);
    const s = (round.words * 0.6 + round.rhymes * 2) * heard + tl.c * WEIGHT.c + tl.l * WEIGHT.l + tl.b * WEIGHT.b;
    return Math.max(0, Math.min(100, Math.round(s)));
  }
  const finalOf = (round, extra = []) => scoreOf(round, CYCLE, extra);

  // The beat: a kick at the top of every beat that decays in 0.18 s.
  function kick(t) {
    const b = ((t % BEAT) + BEAT) % BEAT;
    return Math.exp(-b / 0.12);
  }
  // Mouth: syllables at four per beat while speaking, shaped by the beat.
  function mouth(t, speaking) {
    if (!speaking) return 0;
    const syl = Math.abs(Math.sin((t * Math.PI * 4) / BEAT));
    return clamp(0.25 + 0.75 * syl * (0.55 + 0.45 * kick(t)));
  }
  // Voice level on the mic (0..1): phrases of two beats with short breaths.
  function voice(t) {
    const local = t - turn.from;
    if (local < 0 || local > turn.length) return 0;
    const phraseIn = (local % (2 * BEAT)) / (2 * BEAT);
    const breath = smooth(0, 0.08, phraseIn) * (1 - smooth(0.86, 1, phraseIn));
    const syl = 0.5 + 0.5 * Math.abs(Math.sin(local * 11.3) * Math.cos(local * 4.1));
    return clamp(breath * (0.35 + 0.65 * syl) * smooth(0, 0.3, local));
  }
  const phaseAt = (t) => PHASES.find((p) => t < p.to) ?? PHASES[PHASES.length - 1];
  const typed = (str, from, rate, t) => str.slice(0, clamp(Math.floor((t - from) * rate), 0, str.length));

  return { BPM, BEAT, BAR, PASS, G, CARD, FLY, FEED, ROLL, DROP, T_ROLL, T_DROP, STEPS, PHASES, CYCLE, phase, ROUNDS, WEIGHT, voteTime, castAt, tally, heardAt, scoreOf, finalOf, kick, mouth, voice, phaseAt, typed, smooth, clamp };
})();

